const nav = document.querySelector("#chapter-nav");
const content = document.querySelector("#manual-content");
const search = document.querySelector("#chapter-search");
const searchStatus = document.querySelector("#search-status");
const searchResults = document.querySelector("#search-results");
const chapterGroups = new Map();
const additionalSearchText = {
  "1.1": "供電規劃 1100W 1400W 1+1 熱備援 雙迴路 UPS PDU 110V 220V",
  "1.2": "供電規劃 1100W 1400W 1+1 熱備援 雙迴路 UPS PDU 110V 220V",
  "2.4": "磁碟列表欄位說明 項次 插槽 製造商 介面速度 型號 韌體版本 動作 RAID ID 已使用空間 總容量",
};

function normalizeSearchText(value) {
  return value.replace(/\s+/g, " ").trim().toLowerCase();
}

function createChapterSearchIndex(chapter) {
  const template = document.createElement("template");
  template.innerHTML = chapter.body;
  const elements = [...template.content.children];
  const headingIndexes = elements
    .map((element, index) => element.tagName === "H2" ? index : -1)
    .filter((index) => index >= 0);
  const sharedText = `${chapter.number} ${chapter.title} ${chapter.keywords} ${chapter.lead} ${additionalSearchText[chapter.id] || ""}`;
  const sections = [{
    title: "章節概述",
    text: normalizeSearchText(`${sharedText} ${elements.slice(0, headingIndexes[0] ?? elements.length).map((element) => element.textContent).join(" ")}`),
  }];

  headingIndexes.forEach((start, position) => {
    const end = headingIndexes[position + 1] || elements.length;
    const heading = elements[start];
    sections.push({
      title: heading.textContent.trim(),
      text: normalizeSearchText(elements.slice(start, end).map((element) => element.textContent).join(" ")),
    });
  });
  return { chapter, sections };
}

const chapterSearchIndex = chapters.map(createChapterSearchIndex);

function makeSearchSnippet(text, query) {
  const matchAt = text.indexOf(query);
  const start = Math.max(0, matchAt - 36);
  const end = Math.min(text.length, matchAt + query.length + 72);
  return `${start > 0 ? "…" : ""}${text.slice(start, end)}${end < text.length ? "…" : ""}`;
}

function findSearchMatches(query) {
  return chapterSearchIndex.flatMap(({ chapter, sections }) => sections
    .filter((section) => section.text.includes(query))
    .map((section) => ({ chapter, section, snippet: makeSearchSnippet(section.text, query) })));
}

function renderSearchResults(matches, query) {
  searchResults.replaceChildren();
  searchResults.hidden = !query;
  if (!query) return;

  matches.slice(0, 30).forEach(({ chapter, section, snippet }) => {
    const result = document.createElement("button");
    result.type = "button";
    result.className = "search-result";
    const title = document.createElement("strong");
    const chapterNumber = document.createElement("span");
    chapterNumber.className = "chapter-number";
    chapterNumber.textContent = chapter.number;
    const chapterTitle = document.createElement("span");
    chapterTitle.className = "chapter-title";
    chapterTitle.textContent = chapter.title;
    title.append(chapterNumber, chapterTitle);
    const location = document.createElement("span");
    location.textContent = section.title;
    const preview = document.createElement("small");
    preview.textContent = snippet;
    result.append(title, location, preview);
    result.addEventListener("click", () => selectChapter(chapter.id, section.title, query));
    searchResults.append(result);
  });
}

function highlightMatches(query) {
  if (!query) return;
  const walker = document.createTreeWalker(content, NodeFilter.SHOW_TEXT);
  const textNodes = [];
  while (walker.nextNode()) {
    const node = walker.currentNode;
    if (node.parentElement && !["MARK", "SCRIPT", "STYLE"].includes(node.parentElement.tagName)) textNodes.push(node);
  }
  textNodes.forEach((node) => {
    const text = node.nodeValue;
    const normalized = text.toLowerCase();
    if (!normalized.includes(query)) return;
    const fragment = document.createDocumentFragment();
    let cursor = 0;
    let matchAt = normalized.indexOf(query, cursor);
    while (matchAt >= 0) {
      fragment.append(text.slice(cursor, matchAt));
      const mark = document.createElement("mark");
      mark.className = "search-highlight";
      mark.textContent = text.slice(matchAt, matchAt + query.length);
      fragment.append(mark);
      cursor = matchAt + query.length;
      matchAt = normalized.indexOf(query, cursor);
    }
    fragment.append(text.slice(cursor));
    node.replaceWith(fragment);
  });
}

function renderContent(chapter, sectionTitle, query) {
  document.title = `${chapter.number} ${chapter.title}｜AcroFlex 使用手冊`;
  const parentChapter = chapter.number.split(".")[0];
  content.innerHTML = `<p class="eyebrow">章節 ${chapter.number}</p><h1 class="chapter-heading"><span class="chapter-number" aria-hidden="true">${chapter.number}</span><span class="chapter-title">${chapter.title}</span></h1><p class="lead">${chapter.lead}</p><div class="metadata"><span class="tag">AcroFlex 使用手冊</span>${chapter.level === 2 ? `<span class="tag">第 ${parentChapter} 章子章節</span>` : '<span class="tag">第一層章節</span>'}</div>${chapter.body}`;
  const sectionHeadings = [...content.querySelectorAll("h2")];
  const specificationsHeading = sectionHeadings.find((heading) => heading.textContent === "主機規格");
  const appearanceHeading = sectionHeadings.find((heading) => heading.textContent === "主機外觀");
  if (specificationsHeading && appearanceHeading) {
    const specificationsTable = specificationsHeading.nextElementSibling;
    content.insertBefore(specificationsHeading, appearanceHeading);
    content.insertBefore(specificationsTable, appearanceHeading);
    if (chapter.id === "1.1") {
      const powerPlanning = document.createElement("section");
      powerPlanning.innerHTML = `<h2>供電規劃</h2><p>AHC-F3000 配置 1,100W 以上、1+1 熱備援電源供應器。兩組電源供應器在正常情況下可共同分攤負載；但任一電源、PDU、UPS 或供電迴路異常時，另一組必須能獨立供應整台主機的完整負載。</p><table class="feature-table"><thead><tr><th scope="col">規劃項目</th><th scope="col">建議</th></tr></thead><tbody><tr><td>每迴路容量</td><td>每一條供電迴路應可獨立提供至少 1,100W；建議預留至少 20% 餘裕，以每台主機每迴路 1.32kW 進行容量規劃。</td></tr><tr><td>110V 供電參考</td><td>以 1,100W 計算的理論電流約為 10A；保留 20% 餘裕後約為 12A。若該迴路沒有其他負載，建議每迴路至少使用 15A 以上專用迴路。</td></tr><tr><td>220V 供電參考</td><td>以 1,100W 計算的理論電流約為 5A；保留 20% 餘裕後約為 6A。若該迴路沒有其他負載，建議每迴路至少使用 10A 以上專用迴路。</td></tr><tr><td>雙迴路接法</td><td>電源供應器 A 應接至迴路／UPS／PDU A；電源供應器 B 應接至獨立的迴路／UPS／PDU B。兩者不得共用同一斷路器、同一 UPS 或同一 PDU 的單一上游電源。</td></tr><tr><td>多主機估算</td><td>若有 N 台 AHC-F3000，每個迴路建議容量至少為 N × 1.32kW；並將網路設備、儲存設備及其他同迴路負載一併納入 UPS 與迴路容量計算。</td></tr></tbody></table><div class="callout"><strong>安裝前確認：</strong>1,100W 為電源供應器額定功率，實際輸入電流還會受電源效率、功率因數、磁碟與擴充卡組態影響。最終迴路、插座、UPS 與 PDU 規格應以電源供應器銘牌的輸入額定值、實際組態及合格電氣人員的評估為準。</div>`;
      content.insertBefore(powerPlanning, appearanceHeading);
    }
  }
  if (["1.1", "1.2"].includes(chapter.id)) {
    const rearPanelHeading = sectionHeadings.find((heading) => heading.textContent === "後面板與網路擴充");
    const rearPanelTable = rearPanelHeading?.nextElementSibling;
    if (rearPanelTable?.tagName === "TABLE") {
      const powerPlanning = document.createElement("section");
      powerPlanning.innerHTML = `<h2>供電規劃</h2><p>${chapter.title} 可配置 1,100W 或 1,400W 的 1+1 熱備援電源供應器。1+1 不表示兩條供電迴路各自只需承擔一半負載；為維持單一路電源異常時的可用性，<strong>每一條供電迴路都必須能獨立提供整台主機的完整額定負載</strong>。</p><p>下表以電源供應器額定功率加上 20% 容量餘裕計算，作為每台主機、每一條供電迴路的規劃參考。電流值以 <code>功率 ÷ 電壓</code> 估算，未納入實際電源效率、功率因數或其他同迴路設備負載。</p><table class="feature-table"><thead><tr><th scope="col">電源供應器配置</th><th scope="col">每迴路最低額定功率</th><th scope="col">每迴路規劃功率<br>（含 20% 餘裕）</th><th scope="col">110V 供電參考電流</th><th scope="col">220V 供電參考電流</th></tr></thead><tbody><tr><td>1,100W，1+1 熱備援</td><td>1.10kW</td><td>1.32kW</td><td>約 10A；含餘裕約 12A</td><td>約 5A；含餘裕約 6A</td></tr><tr><td>1,400W，1+1 熱備援</td><td>1.40kW</td><td>1.68kW</td><td>約 12.7A；含餘裕約 15.3A</td><td>約 6.4A；含餘裕約 7.6A</td></tr></tbody></table><h3>雙迴路接法</h3><p>電源供應器 A 應接至迴路／UPS／PDU A；電源供應器 B 應接至獨立的迴路／UPS／PDU B。兩者不得共用同一斷路器、同一 UPS，或同一 PDU 的單一上游電源。若任一路設備失效，另一迴路仍須可維持主機運作。</p><h3>機房電力規劃建議</h3><ul><li>規劃 110V 供電時，1,100W 組態每迴路約需 12A 的規劃容量；1,400W 組態每迴路約需 15.3A。應依迴路的連續負載限制、其他設備負載及電源銘牌額定值選擇足夠容量的專用迴路。</li><li>規劃 220V 供電時，1,100W 組態每迴路約需 6A；1,400W 組態每迴路約需 7.6A 的規劃容量。同樣應一併納入 UPS、PDU、網路設備及其他同迴路負載。</li><li>有 N 台同型主機時，每一供電迴路可先以 N × 每台每迴路規劃功率估算，再加上網路設備、儲存設備與其他負載的容量。</li></ul><div class="callout"><strong>電力安全提醒：</strong>1,100W 與 1,400W 是電源供應器額定功率，不等同於所有組態下的實際輸入功率。最終的斷路器、插座、UPS 與 PDU 規格，必須以電源供應器銘牌的輸入額定值、實際硬體組態、當地電氣規範及合格電氣人員評估為準。</div>`;
      rearPanelTable.insertAdjacentElement("afterend", powerPlanning);
    }
  }
  if (chapter.id === "2.4") {
    const storageFigures = content.querySelectorAll(".storage-screen");
    const firstStorageFigure = storageFigures[0];
    firstStorageFigure.insertAdjacentHTML("afterend", `<h3>磁碟列表欄位說明</h3><table class="feature-table"><thead><tr><th scope="col">欄位</th><th scope="col">說明</th></tr></thead><tbody><tr><td>項次</td><td>磁碟在目前列表中的序號。</td></tr><tr><td>插槽</td><td>對應主機的實體硬碟插槽編號，可用來核對磁碟安裝位置。</td></tr><tr><td>磁碟狀態</td><td>顯示磁碟目前狀態，例如 <code>Unused</code> 表示尚未加入磁碟陣列。</td></tr><tr><td>容量</td><td>顯示該實體磁碟的容量；規劃陣列與熱備援時應一併確認。</td></tr><tr><td>製造商</td><td>顯示硬碟製造商資訊，用於核對硬體配置。</td></tr><tr><td>介面速度</td><td>顯示磁碟介面連線資訊，例如 SATA 連線速度。</td></tr><tr><td>型號</td><td>顯示硬碟型號，可用於確認是否符合採購與部署規格。</td></tr><tr><td>韌體版本</td><td>顯示硬碟目前韌體版本；若需維護或排錯，應記錄此資訊。</td></tr><tr><td>動作</td><td>提供「定位」功能，協助現場人員以定位燈號辨識實體磁碟。</td></tr></tbody></table>`);
    const createdRaidFigure = storageFigures[6];
    createdRaidFigure.insertAdjacentHTML("afterend", `<h3>磁碟陣列列表欄位說明</h3><table class="feature-table"><thead><tr><th scope="col">欄位</th><th scope="col">說明</th></tr></thead><tbody><tr><td>RAID ID</td><td>磁碟陣列的識別編號；後續查看、定位、擴充或維護時，可用此編號辨識目標陣列。</td></tr><tr><td>RAID 級別</td><td>顯示陣列所使用的 RAID 保護方式，例如 <code>RAID 5</code>；應與建置規劃相符。</td></tr><tr><td>已使用空間</td><td>顯示目前已由陣列使用的容量。新建立、尚未投入使用的陣列通常顯示為 <code>0.00 GB</code>。</td></tr><tr><td>總容量</td><td>顯示建立後可供使用的陣列容量，會受成員碟容量、RAID 級別與系統容量換算方式影響。</td></tr><tr><td>狀態</td><td>顯示磁碟陣列目前狀態；<code>Ready</code> 表示陣列已建立完成並可供後續部署流程使用。</td></tr></tbody></table>`);
  }
  highlightMatches(query);
  document.querySelectorAll(".chapter-button").forEach((button) => button.classList.toggle("is-active", button.dataset.id === chapter.id));
  history.replaceState(null, "", `#${chapter.id}`);
  if (sectionTitle && sectionTitle !== "章節概述") {
    const targetHeading = [...content.querySelectorAll("h2")].find((heading) => heading.textContent === sectionTitle);
    if (targetHeading) targetHeading.scrollIntoView({ behavior: "smooth", block: "start" });
  }
}

function selectChapter(id, sectionTitle, query) {
  const chapter = chapters.find((item) => item.id === id) || chapters[1];
  const parentId = chapter.level === 1 ? chapter.id : chapter.id.split(".")[0];
  const parentGroup = chapterGroups.get(parentId);
  if (parentGroup) {
    parentGroup.content.hidden = false;
    parentGroup.toggle.setAttribute("aria-expanded", "true");
  }
  renderContent(chapter, sectionTitle, query);
  content.focus({ preventScroll: Boolean(sectionTitle) });
}

let activeGroup;
chapters.forEach((chapter) => {
  const button = document.createElement("button");
  button.type = "button";
  button.className = `chapter-button level-${chapter.level}`;
  button.dataset.id = chapter.id;
  const chapterNumber = document.createElement("span");
  chapterNumber.className = "chapter-number";
  chapterNumber.textContent = chapter.number;
  const chapterTitle = document.createElement("span");
  chapterTitle.className = "chapter-title";
  chapterTitle.textContent = chapter.title;
  button.append(chapterNumber, chapterTitle);
  button.addEventListener("click", () => selectChapter(chapter.id));

  if (chapter.level === 1) {
    const group = document.createElement("section");
    group.className = "chapter-group";
    const header = document.createElement("div");
    header.className = "chapter-group-header";
    const toggle = document.createElement("button");
    toggle.type = "button";
    toggle.className = "chapter-toggle";
    toggle.setAttribute("aria-label", `展開或收合 ${chapter.title}`);
    toggle.setAttribute("aria-expanded", "false");
    toggle.textContent = "›";
    const children = document.createElement("div");
    children.className = "chapter-children";
    children.hidden = true;
    toggle.addEventListener("click", () => {
      children.hidden = !children.hidden;
      toggle.setAttribute("aria-expanded", String(!children.hidden));
    });
    header.append(toggle, button);
    group.append(header, children);
    nav.append(group);
    activeGroup = { content: children, toggle, group };
    chapterGroups.set(chapter.id, activeGroup);
    return;
  }

  if (activeGroup) activeGroup.content.append(button);
  else nav.append(button);
});

chapterGroups.forEach(({ content, toggle }) => {
  if (!content.childElementCount) {
    toggle.disabled = true;
    toggle.setAttribute("aria-hidden", "true");
  }
});

search.addEventListener("input", () => {
  const query = normalizeSearchText(search.value);
  const matches = query ? findSearchMatches(query) : [];
  const matchingChapterIds = new Set(matches.map(({ chapter }) => chapter.id));
  const visibleChapterIds = new Set(matchingChapterIds);
  matchingChapterIds.forEach((id) => {
    if (id.includes(".")) visibleChapterIds.add(id.split(".")[0]);
  });
  document.querySelectorAll(".chapter-button").forEach((button) => {
    button.hidden = Boolean(query) && !visibleChapterIds.has(button.dataset.id);
  });
  chapterGroups.forEach(({ content, toggle, group }) => {
    const hasVisibleChapter = [...group.querySelectorAll(".chapter-button")].some((button) => !button.hidden);
    group.hidden = !hasVisibleChapter;
    if (query && hasVisibleChapter) {
      content.hidden = false;
      toggle.setAttribute("aria-expanded", "true");
    }
  });
  renderSearchResults(matches, query);
  searchStatus.textContent = query ? `找到 ${matches.length} 個相關段落，分布於 ${matchingChapterIds.size} 個章節` : "";
});

selectChapter(decodeURIComponent(location.hash.slice(1)) || "1.1");
